// Conversation (Dan, 2026-11-10): a short spoken or typed exchange with Claude in the course language, for the
// conversation scenes on the path and the conversation partner in Self-Study. Off until TAMAGO_ANTHROPIC_API_KEY is
// set (a key for Tamago only; a generic ANTHROPIC_API_KEY is never used).
// A small, low-cost model (Haiku 5.5, effort low), a hard limit per conversation (turns and characters), and the
// Tamago workspace's $5 monthly cap. The system prompt and word lists stay the same for a whole conversation, so they
// are cached after the first turn. Meanings never come from here: the app finds the course words in what Claude said
// and takes their meanings from its own Wiktionary data. Never graded.
//   kind "turn": Claude's next line (and, if corrections are on each turn, a note on the learner's last line).
//   kind "review": at the end, when corrections are set to the end, notes on the learner's lines.
import Anthropic from '@anthropic-ai/sdk'

const MODEL = 'claude-haiku-5-5'
export const LIMITS = { turns: 14, chars: 240, words: 400 }
const LANG = { fr: 'French', es: 'Latin American Spanish (use ustedes, never vosotros)', de: 'standard German as spoken in Germany', it: 'standard Italian as spoken in Italy (tu with friends, Lei with strangers)', pt: 'Portuguese as spoken in Brazil (você, never tu; Brazilian spelling and words)', nl: 'standard Dutch as spoken in the Netherlands (je with friends, u with strangers)', pl: 'standard Polish as spoken in Poland (ty throughout, never the formal Pan or Pani)', no: 'Norwegian Bokmål as spoken in Norway (du throughout, never the formal De)', da: 'standard Danish as spoken in Denmark (du throughout, never the formal De)', sv: 'standard Swedish as spoken in Sweden (du throughout, never ni as polite address)' }
const json = (body, status = 200) => new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json', 'cache-control': 'no-store' } })
const clip = (s, n) => String(s ?? '').slice(0, n)

// What each help phrase asks of Claude. The learner taps a phrase (sent in the course language); Claude answers it
// properly, in the course language, never in English.
const HELP = {
  understand: 'The learner said they don\'t understand. Say the same thing again more simply: fewer and easier words, a shorter sentence.',
  slower: 'The learner asked you to speak more slowly. Say your last line again, the same meaning, broken into short pieces. (The app also slows the voice.)',
  repeat: 'The learner asked you to repeat. Say your last line again exactly, word for word.',
  meaning: 'The learner asked what something means (a word they name, or your last line). Explain it in the course language with simpler words, a synonym or a tiny example. Never translate into English.',
  say: 'The learner asked how to say something; the thing may be in English. Give them the course-language word or phrase in a short, natural sentence they can repeat, then carry on.',
  spell: 'The learner asked how to spell something (a word they name, or the main word of your last line). Say the word, then spell it letter by letter with the letters separated by commas so a voice reads them one by one (for example "Bonjour : B, O, N, J, O, U, R."), naming accents the way the language does. Then carry on.',
  word: 'The learner is looking for a word and is describing it ("it\'s a thing for…"). Guess the word, say it clearly, and check if that is what they meant.',
}

// Version 2: pacing, speech-recognition lines, and the gentle corrections of the summary.
const PACE = 'This scene is short: about 6 to 8 exchanges in all, about 2 to 3 minutes. Open the scene\'s task straight away.'
const SPOKEN = 'Said aloud and written down by speech recognition: ignore spelling, capitals and punctuation in it.'
export const paceNote = (n) => n >= 8
  ? `Exchange ${n} of 8: close the scene now in one short, friendly line (a goodbye) and set done to true.`
  : n >= 6 ? `Exchange ${n} of 6 to 8: start to bring the task to an end.` : `Exchange ${n} of 6 to 8.`
const REVIEW_V2 = '[The conversation is over. Pick the 2 or 3 most useful gentle corrections from the learner\'s lines (fewer if there were fewer mistakes, an empty list if none): what they said, a better, natural way in the course language, and why in a few kind, plain English words. Skip help phrases. For lines said aloud, never correct spelling, capitals or punctuation.]'

function system(b) {
  const lang = LANG[b.lang]
  const known = (b.known ?? []).join(', ')
  const pool = (b.pool ?? []).join(', ')
  const level = b.stretch === 'scene'
    ? 'Speak slightly above the learner\'s level on purpose: mostly words from their list, and in each line one or two words or a phrase from the A1 list they may not know yet, so that asking for help is part of the practice.'
    : b.stretch === 'few'
      ? 'Use words from the learner\'s list. Now and then (at most one word in a line) you may use a word from the A1 list that is not in theirs.'
      : 'Use only words from the learner\'s list (and names). If you need another word, choose a different way to say it.'
  return `You are a friendly conversation partner for an English speaker learning ${lang} at CEFR A1, in a language-learning app.
Speak only ${lang}. Never use English in what you say, even when explaining.
Keep every line short: one or two sentences, at most about 15 words in all. Ask one simple question at a time to keep the conversation going.
${level}
Be warm and natural; never grade, praise effusively or lecture. Don't use emoji, lists or markdown.
The learner may tap help phrases. When they do, help properly and in ${lang}: slow down, repeat, rephrase or explain, then carry on.
Stay in the scene. If the learner writes in English, answer in simple ${lang} and help them say it.

Scene: ${clip(b.scene?.title, 80)}. ${clip(b.scene?.setting, 300)}
You are: ${clip(b.scene?.ai, 120)}. The learner is: ${clip(b.scene?.learner, 120)}.

The learner's words (forms they have met): ${known || '(very few yet)'}
A1 words of the course: ${pool}
Names you may use: ${(b.names ?? []).join(', ') || 'none'}`
}

const TURN = {
  type: 'object', additionalProperties: false, required: ['say', 'english', 'correction', 'done'],
  properties: {
    say: { type: 'string', description: 'Your next line, in the course language only.' },
    english: { type: 'string', description: 'A plain English translation of your line, shown only if the learner asks.' },
    correction: { type: 'string', description: 'Empty unless corrections are on each turn and the learner\'s last line had a mistake: then the corrected line in the course language, a dash, and a few English words on why.' },
    done: { type: 'boolean', description: 'True when the scene has reached a natural end.' },
  },
}
const MESSAGE = {
  type: 'object', additionalProperties: false, required: ['meaning', 'grammar', 'missing', 'better'],
  properties: {
    meaning: { type: 'string', description: 'One plain English sentence: does the message get its point across?' },
    grammar: { type: 'array', items: { type: 'string' }, description: 'Up to 3 short English notes on mistakes, each quoting the words and the fix.' },
    missing: { type: 'array', items: { type: 'string' }, description: 'Points of the task the message does not cover yet, in English.' },
    better: { type: 'string', description: 'The message rewritten correctly in the course language, staying close to what the learner wrote.' },
  },
}
const REVIEW = {
  type: 'object', additionalProperties: false, required: ['notes'],
  properties: { notes: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['said', 'better', 'why'], properties: { said: { type: 'string' }, better: { type: 'string' }, why: { type: 'string' } } } } },
}

export async function handle(req, key) {
  if (req.method === 'GET') return json({ ready: Boolean(key), limits: LIMITS })
  if (req.method !== 'POST') return json({ error: 'method' }, 405)
  if (!key) return json({ ready: false, error: 'needs setup' }, 503)
  const origin = req.headers.get('origin')
  if (origin && new URL(origin).host !== new URL(req.url).host) return json({ error: 'origin' }, 403)

  let b
  try { b = await req.json() } catch { return json({ error: 'body' }, 400) }
  if (!LANG[b.lang]) return json({ error: 'lang' }, 400)
  // QT16 (A1 Complete): notes on a short written message. Not scored; one call per message.
  if (b.kind === 'message') {
    const client = new Anthropic({ apiKey: key })
    try {
      const res = await client.messages.create({
        model: MODEL, max_tokens: 1500,
        output_config: { effort: 'low', format: { type: 'json_schema', schema: MESSAGE } },
        system: `You read a short message an English speaker learning ${LANG[b.lang]} at CEFR A1 wrote for a task, and give brief, kind notes in plain English. No praise beyond a word, no grade, no markdown. Judge only against A1: simple sentences are right.`,
        messages: [{ role: 'user', content: `Task: ${clip(b.prompt, 300)}\nPoints to cover: ${(Array.isArray(b.points) ? b.points : []).slice(0, 6).map((p) => clip(p, 120)).join('; ') || 'none listed'}\nThe learner's message:\n${clip(b.text, 800)}` }],
      })
      if (res.stop_reason === 'refusal' || res.stop_reason === 'max_tokens') return json({ result: null })
      return json({ result: JSON.parse(res.content.filter((c) => c.type === 'text').map((c) => c.text).join('')) })
    } catch (error) {
      if (error instanceof SyntaxError) return json({ result: null })
      if (error instanceof Anthropic.RateLimitError) return json({ error: 'busy' }, 429)
      if (error instanceof Anthropic.APIError) return json({ error: 'api' }, 502)
      return json({ error: 'network' }, 502)
    }
  }
  const kind = b.kind === 'review' ? 'review' : 'turn'
  const history = (Array.isArray(b.messages) ? b.messages : []).slice(0, LIMITS.turns * 2 + 2)
  const learnerTurns = history.filter((m) => m.role === 'learner').length
  if (kind === 'turn' && learnerTurns > LIMITS.turns) return json({ error: 'limit' }, 429)
  const body = {
    lang: b.lang, scene: b.scene ?? {}, stretch: ['scene', 'few', 'mine'].includes(b.stretch) ? b.stretch : 'mine',
    known: (Array.isArray(b.known) ? b.known : []).slice(0, LIMITS.words).map((w) => clip(w, 30)),
    pool: (Array.isArray(b.pool) ? b.pool : []).slice(0, LIMITS.words).map((w) => clip(w, 30)),
    names: (Array.isArray(b.names) ? b.names : []).slice(0, 10).map((n) => clip(n, 30)),
  }
  // The conversation as alternating turns; Claude speaks first, so a "start" user turn opens it. A help tap carries
  // its instruction in brackets after the learner's words.
  const v2 = b.v === 2
  const messages = [{ role: 'user', content: `(The conversation starts. Say your first line.)${v2 ? `\n[${PACE}]` : ''}` }]
  let answered = 0
  for (const m of history) {
    if (m.role === 'ai') { messages.push({ role: 'assistant', content: JSON.stringify({ say: clip(m.text, LIMITS.chars), english: '', correction: '', done: false }) }); continue }
    if (!m.help) answered++
    messages.push({ role: 'user', content: `${clip(m.text, LIMITS.chars)}${m.spoken ? `\n[${SPOKEN}]` : ''}${HELP[m.help] ? `\n[${HELP[m.help]}]` : ''}${b.corrections === 'each' && !m.help ? '\n[Corrections are on: fill in correction if this line has a mistake.]' : ''}` })
  }
  // Version 2 (Dan, 2026-11-15): 6 to 8 exchanges. The count rides on the newest turn, so the cached prompt stays put.
  if (v2 && kind === 'turn' && history.at(-1)?.role === 'learner') messages.push({ role: 'user', content: `[${paceNote(answered)}]` })
  if (kind === 'review') messages.push({ role: 'user', content: v2 ? REVIEW_V2 : '[The conversation is over. List up to 5 of the learner\'s lines that had a mistake: what they said, a better way in the course language, and why in a few plain English words. Skip help phrases. An empty list if there were none.]' })
  // Merge any two user turns in a row (the API takes them, but one turn reads more clearly).
  const merged = messages.reduce((a, m) => { const last = a.at(-1); if (last && last.role === m.role) last.content += `\n${m.content}`; else a.push({ ...m }); return a }, [])

  // The key goes in explicitly, so the SDK never falls back to ANTHROPIC_API_KEY.
  const client = new Anthropic({ apiKey: key })
  try {
    const res = await client.messages.create({
      model: MODEL,
      max_tokens: 1500,
      cache_control: { type: 'ephemeral' },
      output_config: { effort: 'low', format: { type: 'json_schema', schema: kind === 'review' ? REVIEW : TURN } },
      system: system(body),
      messages: merged,
    })
    if (res.stop_reason === 'refusal' || res.stop_reason === 'max_tokens') return json({ result: null })
    const text = res.content.filter((c) => c.type === 'text').map((c) => c.text).join('')
    return json({ result: JSON.parse(text) })
  } catch (error) {
    if (error instanceof SyntaxError) return json({ result: null })
    if (error instanceof Anthropic.RateLimitError) return json({ error: 'busy' }, 429)
    if (error instanceof Anthropic.AuthenticationError) return json({ error: 'key' }, 503)
    if (monthlyLimit(error)) return json({ error: 'monthly' }, 503)
    if (error instanceof Anthropic.APIError) return json({ error: 'api' }, 502)
    return json({ error: 'network' }, 502)
  }
}

// The workspace's monthly spend limit (or an empty balance): Anthropic refuses with a 400 that names usage limits or
// credit. The app says so plainly instead of "try again".
export const monthlyLimit = (error) => error instanceof Anthropic.APIError && error.status === 400 && /usage limit|spend limit|credit balance/i.test(String(error.message))

files.server/explain.mjs:
// Claude explains a mistake on a typed answer (Phase 4). Off until Dan sets TAMAGO_ANTHROPIC_API_KEY as a Cloudflare Pages secret
// (a key for Tamago only; a generic ANTHROPIC_API_KEY from another project is never used): GET reports whether it's ready, so the app shows nothing in lessons until it is.
// Facts stay out of the model's memory: it may only use the sentence, the accepted answers and the Wiktionary
// hints the app sends. A smaller, faster model (feature list: "a smaller, cheaper model for answer checking").
import Anthropic from '@anthropic-ai/sdk'

const MODEL = 'claude-haiku-5-5'
const SYSTEM = `You explain one mistake to an English speaker learning French at CEFR A1.
You get the exercise, the learner's answer, the accepted answers, and word meanings taken from Wiktionary.
Speak to the learner directly, as "you" ("You wrote maison; elles means they."). Never say "the learner".
Reply with one or two short, plain sentences saying what differs between what they wrote and the closest accepted answer, and why it matters.
Use only the information given. Do not define words or give verb forms beyond the meanings and answers provided; if the reason can't be told from them, just name the difference.
No greeting, no praise, no exclamation marks, no lists, no markdown.`

const json = (body, status = 200) => new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json', 'cache-control': 'no-store' } })
const clip = (s, n) => String(s ?? '').slice(0, n)

// Shared by the Cloudflare Pages Function (functions/api/) and the old Netlify one; each passes in its own
// TAMAGO_ANTHROPIC_API_KEY.
export async function handle(req, key) {
  const ready = Boolean(key)
  if (req.method === 'GET') return json({ ready })
  if (req.method !== 'POST') return json({ error: 'method' }, 405)
  if (!ready) return json({ ready: false, error: 'needs setup' }, 503)
  // Only the app's own pages may ask (a light guard until sign-in gives a real per-learner limit).
  const origin = req.headers.get('origin')
  if (origin && new URL(origin).host !== new URL(req.url).host) return json({ error: 'origin' }, 403)

  let b
  try { b = await req.json() } catch { return json({ error: 'body' }, 400) }
  const exercise = b.direction === 'en_to_fr' ? 'Translate into French' : b.direction === 'fr_to_en' ? 'Translate into English' : 'Write the French sentence'
  const hints = (Array.isArray(b.hints) ? b.hints : []).slice(0, 12).map((h) => `${clip(h.form, 40)} = ${clip(h.hint, 80)}`).join('\n')
  const accepted = (Array.isArray(b.accepted) ? b.accepted : []).slice(0, 8).map((a) => `- ${clip(a, 200)}`).join('\n')
  const prompt = `Exercise: ${exercise}
Prompt shown: ${clip(b.shown, 200)}
Your answer (the learner's): ${clip(b.given, 200)}
Accepted answers:
${accepted}
Word meanings (Wiktionary):
${hints || '(none)'}`

  // The key is passed explicitly, so the SDK never falls back to ANTHROPIC_API_KEY.
  const client = new Anthropic({ apiKey: key })
  try {
    const res = await client.messages.create({
      model: MODEL,
      max_tokens: 2000,
      output_config: { effort: 'low' },
      system: SYSTEM,
      messages: [{ role: 'user', content: prompt }],
    })
    if (res.stop_reason === 'refusal') return json({ explanation: null })
    const text = res.content.filter((c) => c.type === 'text').map((c) => c.text).join(' ').trim()
    return json({ explanation: text || null })
  } catch (error) {
    if (error instanceof Anthropic.RateLimitError) return json({ error: 'busy' }, 429)
    if (error instanceof Anthropic.AuthenticationError) return json({ error: 'key' }, 503)
    if (error instanceof Anthropic.APIError) return json({ error: 'api' }, 502)
    return json({ error: 'network' }, 502)
  }
}

files.server/generate.mjs:
// Learner-guided content (Phase 5): Claude writes practice material from the words a learner has met, in Tamago's
// shapes. Off until Dan sets TAMAGO_ANTHROPIC_API_KEY (a key for Tamago only; a generic ANTHROPIC_API_KEY is never
// used). The app re-checks every French line against its own word list (Wiktionary-backed) and drops anything
// outside it, so meanings never come from the model.
//   kind "sentences": short practice sentences.
//   kind "listening": a short two-person exchange with three comprehension questions (QT20).
import Anthropic from '@anthropic-ai/sdk'

const MODEL = 'claude-opus-5-5'
const json = (body, status = 200) => new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json', 'cache-control': 'no-store' } })
const clip = (s, n) => String(s ?? '').slice(0, n)

const RULES = `You write French practice material for an English speaker at CEFR A1.
Use only the French words in the list you are given, in the forms listed (you may add punctuation, and the names listed). Never use a French word that is not in the list.
Keep sentences short, natural and literal; nothing idiomatic. The English is a plain, faithful translation.`

const SCHEMAS = {
  sentences: {
    type: 'object', additionalProperties: false, required: ['sentences'],
    properties: { sentences: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['french', 'english'], properties: { french: { type: 'string' }, english: { type: 'string' } } } } },
  },
  listening: {
    type: 'object', additionalProperties: false, required: ['title', 'lines', 'questions'],
    properties: {
      title: { type: 'string' },
      lines: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['speaker', 'french', 'english'], properties: { speaker: { type: 'string', enum: ['A', 'B'] }, french: { type: 'string' }, english: { type: 'string' } } } },
      questions: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['question', 'choices', 'answer'], properties: { question: { type: 'string' }, choices: { type: 'array', items: { type: 'string' } }, answer: { type: 'integer' } } } },
    },
  },
}
const TASKS = {
  sentences: (n, focus) => `Write ${n} different practice sentences${focus ? ` about: ${focus}` : ''}. Vary the sentence patterns.`,
  listening: (_, focus) => `Write a short exchange of 4 to 6 lines between two people, A and B${focus ? `, about: ${focus}` : ''}. Then write 3 questions in English about what was said, each with 3 short English choices and the index (0, 1 or 2) of the right one. A question must be answerable only by understanding the French.`,
}

// Shared by the Cloudflare Pages Function (functions/api/) and the old Netlify one; each passes in its own
// TAMAGO_ANTHROPIC_API_KEY.
export async function handle(req, key) {
  if (req.method === 'GET') return json({ ready: Boolean(key) })
  if (req.method !== 'POST') return json({ error: 'method' }, 405)
  if (!key) return json({ ready: false, error: 'needs setup' }, 503)
  const origin = req.headers.get('origin')
  if (origin && new URL(origin).host !== new URL(req.url).host) return json({ error: 'origin' }, 403)

  let b
  try { b = await req.json() } catch { return json({ error: 'body' }, 400) }
  const kind = b.kind in SCHEMAS ? b.kind : null
  if (!kind) return json({ error: 'kind' }, 400)
  const words = (Array.isArray(b.words) ? b.words : []).slice(0, 150).map((w) => `${clip(w.form, 40)} (${clip(w.hint, 60)})`)
  if (words.length < 10) return json({ error: 'words' }, 400)
  const names = (Array.isArray(b.names) ? b.names : []).slice(0, 10).map((n) => clip(n, 30))
  const count = Math.min(Math.max(Number(b.count) || 6, 1), 8)

  // The key goes in explicitly, so the SDK never falls back to ANTHROPIC_API_KEY.
  const client = new Anthropic({ apiKey: key })
  try {
    const res = await client.beta.messages.create({
      model: MODEL,
      max_tokens: 8000,
      betas: ['server-side-fallback-2026-07-01'],
      fallbacks: 'default',
      output_config: { effort: 'low', format: { type: 'json_schema', schema: SCHEMAS[kind] } },
      system: RULES,
      messages: [{ role: 'user', content: `French words you may use (meaning in brackets):\n${words.join('\n')}\n\nNames you may use: ${names.join(', ') || 'none'}\n\n${TASKS[kind](count, clip(b.focus, 80))}` }],
    })
    if (res.stop_reason === 'refusal' || res.stop_reason === 'max_tokens') return json({ result: null })
    const text = res.content.filter((c) => c.type === 'text').map((c) => c.text).join('')
    return json({ result: JSON.parse(text) })
  } catch (error) {
    if (error instanceof SyntaxError) return json({ result: null })
    if (error instanceof Anthropic.RateLimitError) return json({ error: 'busy' }, 429)
    if (error instanceof Anthropic.AuthenticationError) return json({ error: 'key' }, 503)
    if (error instanceof Anthropic.APIError) return json({ error: 'api' }, 502)
    return json({ error: 'network' }, 502)
  }
}

files.scripts/audit/logic-audit.mjs:
// Playthrough audit, every-lesson check (Dan, 2026-11-12): every question of every lesson as one learner walks each
// course in tree order. Choices (duplicates, near-duplicates by punctuation or contraction, a wrong choice that's also
// right, a picture twice, a cognate pair), whether the right answer is accepted and a wrong one refused, whether the
// chips can build the answer, translations, recordings on disk and whether a Lingua Libre recording names the same
// word. Writes JSON to the path given (default logic-issues.json in the working directory).
//   node scripts/audit/logic-audit.mjs [out.json]
import { existsSync, writeFileSync } from 'node:fs'
import { checkTyped, sameAnswer } from '../../src/lib/check.js'
import { isCognate } from '../../src/lib/lesson.js'
import { COURSES, tablesOf, walk } from './walk.mjs'

const out = process.argv[2] ?? 'logic-issues.json'
const fold = (t) => String(t ?? '').toLowerCase().normalize('NFD').replace(/\p{M}/gu, '').replace(/[’ʼ]/g, "'").replace(/[^\p{L}\p{N}' ]/gu, ' ').replace(/\s+/g, ' ').trim()
const core = (h) => String(h ?? '').toLowerCase().replace(/\(.*?\)/g, '').replace(/[^\p{L}\p{N}' ]/gu, ' ').replace(/\s+/g, ' ').trim()
const issues = new Map()
const add = (key, issue) => { const x = issues.get(key); if (x) x.count++; else issues.set(key, { ...issue, count: 1 }) }
const stats = {}
const fileOk = (f) => !f || existsSync(`public${decodeURI(f)}`)
const llWord = (ll) => { const m = /-([^-]+)\.(wav|ogg|mp3|flac)$/i.exec(ll?.file ?? ''); return m ? fold(m[1].replace(/_/g, ' ')) : null }

for (const [course, dir] of COURSES) {
  const t = tablesOf(dir)
  const st = stats[course] = { questions: 0, lessons: 0, byType: {} }
  walk(t, (q, { u, c, round, lesson, newHere }) => {
    st.questions++; st.byType[q.type] = (st.byType[q.type] ?? 0) + 1
    const at = { course, circle: u.title, round, lesson, type: q.type, where: 'logic' }
    const k = (what) => `${course}|${q.sentence_id ?? q.word_id ?? (q.word_ids ?? []).join(',')}|${q.type}|${what}`
    const vocab = c.vocabulary?.[q.lang] ?? new Set()
    if (q.choices) {
      const texts = q.choices.map((x) => (typeof x === 'string' ? x : x.label ?? x.alt ?? x.word_id))
      if (texts.some((x) => !String(x ?? '').trim())) add(k('empty'), { ...at, issue: `empty choice among ${JSON.stringify(texts)}`, severity: 'high' })
      const meaningType = q.type === 'QT03' || (q.type === 'QT04' && q.variant === 'V0404')
      const alike = texts.some((a, i) => texts.some((b, j) => j > i && (fold(a) === fold(b) || (meaningType && sameAnswer(a, b, 'en')))))
      if (alike && q.type !== 'QT02') add(k('dup'), { ...at, issue: `choices read the same: ${JSON.stringify(texts)}`, severity: 'high' })
      if (meaningType) {
        const right = [q.answer, ...t.accepted_answers.filter((a) => a.sentence_id === q.sentence_id && a.direction === 'fr_to_en').map((a) => a.answer)]
        for (const ch of q.choices) if (ch !== q.answer && right.some((r) => sameAnswer(ch, r, 'en'))) add(k('also right'), { ...at, issue: `the wrong choice "${ch}" is also right for "${q.french}"`, severity: 'high' })
      }
      if (q.type === 'QT02') {
        if (new Set(q.choices.map((x) => x.image)).size !== q.choices.length) add(k('picture twice'), { ...at, issue: `a picture twice: ${q.choices.map((x) => `${x.alt}=${x.image.split('/').pop()}`).join(', ')}`, severity: 'high' })
        if (new Set(q.choices.map((x) => core(x.alt))).size !== q.choices.length) add(k('meaning twice'), { ...at, issue: `a meaning twice: ${q.choices.map((x) => x.alt).join(', ')}`, severity: 'high' })
      }
    }
    if (q.audioChoices && new Set(q.audioChoices.map((a) => fold(a.french))).size !== q.audioChoices.length) add(k('audio dup'), { ...at, issue: 'audio choices say the same thing', severity: 'high' })
    if (q.pairs) {
      if (new Set(q.pairs.map((p) => core(p.hint))).size !== q.pairs.length) add(k('pair meaning'), { ...at, issue: `two pairs share a meaning: ${q.pairs.map((p) => `${p.form}=${p.hint}`).join(', ')}`, severity: 'high' })
      for (const p of q.pairs) {
        if (isCognate(p)) add(`${course}|cognate|${p.word_id}`, { ...at, issue: `a pair reads the same as its meaning: ${p.form} = ${p.hint}`, severity: 'low' })
        if (!String(p.hint ?? '').trim()) add(`${course}|hint|${p.word_id}`, { ...at, issue: `match pair "${p.form}" has no meaning`, severity: 'high' })
        if (!fileOk(p.audio?.file)) add(`${course}|file|${p.audio.file}`, { ...at, issue: `recording missing on disk: ${p.audio.file}`, severity: 'medium' })
      }
    }
    if (q.sentence_id && !String(q.english ?? '').trim()) add(k('no english'), { ...at, issue: 'sentence has no English translation', severity: 'high' })
    for (const sg of q.segments ?? []) if (sg.word_id && newHere.includes(sg.word_id) && !sg.hint && ['QT03', 'QT05', 'QT06'].includes(q.type)) add(`${course}|nohint|${sg.word_id}`, { ...at, issue: `new word "${sg.text}" shown with no meaning under it`, severity: 'medium' })
    if (q.audio?.file) {
      if (!fileOk(q.audio.file)) add(`${course}|file|${q.audio.file}`, { ...at, issue: `recording missing on disk: ${q.audio.file}`, severity: 'medium' })
      const s = c.sentenceById.get(q.sentence_id)
      const said = llWord(s?.lingua_libre)
      if (said && fold(q.french) !== said && !fold(q.french).split(' ').every((w) => said.split(' ').includes(w))) add(k('ll'), { ...at, issue: `recording is Lingua Libre "${said}" but the sentence reads "${q.french}"`, severity: 'high' })
    }
    if (q.accepted?.length) {
      const opts = { lang: q.lang, vocabulary: vocab }
      if (!checkTyped(q.accepted[0], q.accepted, opts).correct) add(k('main'), { ...at, issue: `the main answer "${q.accepted[0]}" is marked wrong`, severity: 'critical' })
      if (q.chips) {
        const src = q.type === 'QT06' ? null : q.type === 'QT09' ? t.sentences.find((x) => x.french === q.shown) : c.sentenceById.get(q.sentence_id)
        const intended = q.type === 'QT06' ? q.english.replace(/[.,!?;:]/g, ' ').split(/\s+/).filter(Boolean) : (c.swBySentence.get(src?.sentence_id) ?? []).map((row) => (row.notes === 'name' ? row.surface : String(row.surface).toLowerCase()))
        if (q.type === 'QT06' || src) {
          const bag = [...q.chips]
          const missing = intended.filter((x) => { const i = bag.indexOf(x); if (i < 0) return true; bag.splice(i, 1); return false })
          if (missing.length || !intended.length) add(k('chips'), { ...at, issue: `the chips can't build "${q.shown}" (missing ${JSON.stringify(missing)})`, severity: 'critical' })
          else if (!checkTyped(intended.join(' '), q.accepted, opts).correct) add(k('chip answer'), { ...at, issue: `building the answer from chips ("${intended.join(' ')}") is marked wrong`, severity: 'critical' })
        }
      }
      const w = q.accepted[0].split(/\s+/)
      if (w.length >= 3) {
        const wrong = w.slice(0, -1).join(' ')
        if (!q.accepted.some((a) => fold(a) === fold(wrong)) && checkTyped(wrong, q.accepted, opts).correct) add(k('wrong ok'), { ...at, issue: `a wrong answer ("${wrong}") is marked right`, severity: 'high' })
      }
      if (checkTyped('zzz qqq', q.accepted, opts).correct) add(k('nonsense'), { ...at, issue: 'nonsense is marked right', severity: 'critical' })
    }
  }, () => { st.lessons++ })
}
const list = [...issues.values()]
writeFileSync(out, JSON.stringify({ stats, issues: list }, null, 1))
const by = {}
for (const i of list) { const kk = `${i.course} | ${i.issue.replace(/["(:].*$/, '').trim()} | ${i.severity}`; by[kk] = (by[kk] ?? 0) + 1 }
console.log(JSON.stringify(Object.fromEntries(Object.entries(stats).map(([k, v]) => [k, { lessons: v.lessons, questions: v.questions }]))))
console.log(Object.entries(by).sort().map(([kk, v]) => `${v}\t${kk}`).join('\n') || 'no issues')

